var a=[{title:`Cosa fa ciascuna regione`,text:`La colonna toracica è la sezione centrale della schiena e ti permette di ruotare ed estendere. Il complesso della spalla comprende l’articolazione sferica e la scapola che scivola sulla gabbia toracica. Raggiungere in alto sopra la testa dipende da diverse regioni che lavorano insieme, quindi verifica più della flessibilità dell’articolazione della spalla.`},{title:`Esplora un movimento comodo`,text:`Un esercizio di rotazione a libro aperto gira con delicatezza la parte superiore del corpo mentre i fianchi restano abbastanza fermi. I cerchi controllati con le braccia ripassano il movimento della spalla, e il cat-cow muove la colonna tra flessione ed estensione a un ritmo facile. Muoviti lentamente, respira normalmente e non forzare la posizione finale.`},{title:`La mobilità nei tuoi sollevamenti`,text:`La distensione sopra la testa può risultare più fluida quando costole, scapole e braccia si muovono insieme. Nei rematori, lascia che le scapole si muovano naturalmente; non devi tenerle ferme indietro per tutto il tempo. Punta a un controllo fluido nell’esercizio che hai scelto. Non esiste un’unica postura rigida che tutti devono copiare.`},{title:`Mobilità più forza`,text:`Distensioni leggere, wall slide, rematori e carry controllati sviluppano insieme range utilizzabile e coordinazione. Lo stretching da solo può migliorare la flessibilità passiva senza darti il pieno controllo sotto carico. Se un esercizio sembra instabile o scomodo, cambia presa, angolo o range di movimento.`},{title:`Usare TrainUp`,text:`Se il lavoro sopra la testa dà fastidio alla spalla, aggiungi la spalla come limitazione in Profilo, con una nota. Il piano sceglie solo esercizi adatti alle tue limitazioni. Per un dolore alla spalla nuovo, persistente o che peggiora, rivolgiti a un medico o a un fisioterapista invece di affidarti a esercizi generici di mobilità.`}];var o=[{label:`ACE 2026: mobilità e flessibilità a confronto`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: indicazioni pratiche sullo stretching`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Libreria di esercizi ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var l={sections:a,sources:o};export{l as default,a as sections,o as sources};